def _login_and_navigate_to_pim(page) -> PIMPage:
    """Navigate to app. Handles session expiry automatically. Returns PIMPage."""
    login_page = LoginPage(page)
    page.goto(url, wait_until="domcontentloaded")
    SessionManager.ensure_authenticated(page, url, username, password, storage_state_path)
    login_page.verify_dashboard()
    pim_page = PIMPage(page)
    pim_page.navigate_to_pim()
    return pim_page


