    @allure.story("Security Testing")
    @allure.title("TC-SRCH-008: Search with SQL injection payload — handled safely")
    @allure.severity(allure.severity_level.CRITICAL)
    def test_search_sql_injection_in_name(self, page):
        """Enter SQL injection in search and verify no SQL error is exposed.
        Test Data: No Excel data needed — uses hardcoded SQL injection payload.
        """
        cloud_env   = read_cloud_env()
        sql_payload = "' OR '1'='1"

        with allure.step("Login and navigate to PIM"):
            pim_page = _login_and_navigate_to_pim(page)
        with allure.step(f"Enter SQL injection payload: '{sql_payload}'"):
            try:
                pim_page.search_employee_by_name(sql_payload)
                result("passed", "SQL payload submitted without crash", "Search submitted")
            except Exception as exc:
                result("failed", "SQL payload submitted without crash", f"Error: {exc}")
                raise
        with allure.step("Verify no SQL error is exposed in page content"):
            try:
                content = page.content()
                sql_keywords = ["sql", "syntax error", "mysql", "postgresql",
                                "ora-", "sqlite", "database error"]
                exposed = any(kw in content.lower() for kw in sql_keywords)
                assert not exposed, "SQL error keywords found — possible SQL injection vulnerability!"
                result("passed", "No SQL error should be exposed", "No SQL error keywords found")
            except AssertionError as exc:
                result("failed", "No SQL error should be exposed", f"SECURITY RISK: {exc}")
                raise

    @allure.story("Security Testing")
    @allure.title("TC-SRCH-009: Search with XSS payload in name field — input sanitized")
    @allure.severity(allure.severity_level.CRITICAL)
    def test_search_xss_payload_in_name(self, page):
        """Enter XSS payload in search and verify no script execution.
        Test Data: No Excel data needed — uses hardcoded XSS payload.
        """
        cloud_env   = read_cloud_env()
        xss_payload = "<script>alert('xss')</script>"

        alert_triggered = {"value": False}
        page.on("dialog", lambda d: (setattr(alert_triggered, "value", True) or d.dismiss()))

        with allure.step("Login and navigate to PIM"):
            pim_page = _login_and_navigate_to_pim(page)
        with allure.step(f"Enter XSS payload: '{xss_payload}'"):
            try:
                pim_page.search_employee_by_name(xss_payload)
                result("passed", "XSS payload submitted without crash", "Search submitted")
            except Exception as exc:
                result("failed", "XSS payload submitted without crash", f"Error: {exc}")
                raise
        with allure.step("Verify no JavaScript alert was triggered"):
            try:
                assert not alert_triggered["value"], "XSS alert triggered — input NOT sanitized!"
                result("passed", "No alert should be triggered", "No alert triggered")
            except AssertionError as exc:
                result("failed", "No alert should be triggered", f"SECURITY RISK: {exc}")
                raise
        with allure.step("Verify no unescaped script tags in page content"):
            try:
                assert xss_payload not in page.content(), "Unescaped XSS tag found in page!"
                result("passed", "No unescaped script tags", "Page content is safe")
            except AssertionError as exc:
                result("failed", "No unescaped script tags", f"XSS tag found: {exc}")
                raise
